(2809, 15692, 'Intellegerem visa sumus probo quando fortepossumus aristoteles igitur anteponam facta oportere libero mordicus iacent', '2646a07a', 4, 'no'),
(2810, 15693, 'Honeste re instituto quaerimus coniunctio danda pudori maximarum optimus amicitias particulas invectio instituto accederem', '810a8fd8', 1, 'no'),
(2811, 15693, '[TRUE] - Dixi voluptates instituta debent neglegatur respondere dogmata verum homini petitur ipsam nova audis habeat stabile', '3d0b64e5', 2, 'yes'),
(2812, 15694, 'Etiamsi occurrent expectare consulat saepiusque facillimum valitudo praeterea finxerit quaerenda sententias libero', '77095e9c', 1, 'no'),
(2813, 15694, 'Historia quicquid luxuriae deprimet elegantius veni declinavi industriae discedere animantium more umquam sciant dogmata firmum', 'a4c910ff', 2, 'no'),
(2814, 15694, ' [TRUE] - Dulce despiciendis parens aeque q sui exclusis sane affectiones opportune', 'b0099d8b', 3, 'yes'),
(2815, 15694, ' [TRUE] - Illi iudicabis facta sponte sit hominem iocabor fuit intuens uberiora contra vicimus alumni sequetur corpusne', 'a6fce4b2', 4, 'yes'),
(2816, 15695, '[TRUE] - Adulter dolore stabilem concedis avarus philodemum arcesilas frater maximas mortuum fugimus', '467c32e6', 1, 'yes'),
(2817, 15695, 'Contemnunt contempsisse nostris utebare intellegatur nihil sententiis ingenium oportebit cupiditatem ennius quodam quali', '3311c40c', 2, 'no'),
(2818, 15696, ' [TRUE] - Pugnem disserendum leve iustus patientiae essentne occurreret improbo censore moribus opera pericli adulter vocant consectetur', '3beca6b2', 1, 'yes'),
(2819, 15696, 'Grandioribus sequebatur cicuta infelix vitiosa sensus attinet amotio leves honesta illuc adhibita interesset consuetudo repudiandum', 'a3560fb5', 2, 'no'),
(2820, 15696, ' [TRUE] - Nostrane defecerit secutus referas assignatum sed potestne suspectum animo dederetur faciamus sumus roga prodest constituendo', '2fc2043d', 3, 'yes'),
(2821, 15696, 'Ordiendum dolori faciliorem reddes docui eae cenabat triarius tuis sententiam expetitur miser ambobus ludus', '75c4d447', 4, 'no'),
(2822, 15697, 'Haesitaret delectant dubia verbi comparandam imperitos peducaeus cornibus posse statuam tres diem repellant debilitas', 'c5065dd3', 1, 'no'),
(2823, 15697, 'Cato sitne nullo potest mortuus haberem oportebit ducitur tuo consequentia utrumque controversiam multarum neglegi uno', '1d957276', 2, 'no'),
(2824, 15697, ' [TRUE] - Affecit citius convenienter pars cantibus tubuli fingunt venissem ipsius igitur d pudori', 'bba6a72e', 3, 'yes'),
(2825, 15697, 'Finxerit stoicis paulo quisque per senatu divitiarum pridem putamus fortitudinis respondeas quanto peripateticus', '1c7cd54d', 4, 'no'),
(2826, 15698, '[TRUE] - Deserunt asotos mendicus exponere tractat exorsus aequas cyrenaici neglegatur clariora litigiosam paulo', 'f833e2ba', 1, 'yes'),
(2827, 15698, 'Laudat fictas putas exorsus expetunt officii oratores erunt discendi ambobus molliorque meum dixti', '555d6505', 2, 'no'),
(2828, 15699, '[TRUE] - Erat adipiscing etenim vetant praesidium condemnatus venissem beatos nosse sententia censet privasse fuisse obscurari acceperit', '64eb2f8f', 1, 'yes'),
(2829, 15699, 'Verso plato sextilius defendere superiori apud sumus levis saneque antiquorum rem', 'af97c912', 2, 'no'),
(2830, 15699, 'Aliquem mendicus deserit ennius vulgo habitus estmata summis sumo ipsos barbarorum', '54607fd1', 3, 'no'),
(2831, 15699, 'Succumbere congressu iudicia theophrasto amarum sensitque appellatum longi divitem magnificentia mitigari acupensere beatum ludimur', '933db40d', 4, 'no'),
(2832, 15700, '[TRUE] - Saepiusque mala errat iudicari domus democrito relictae nostris vacua probarem alienae quas singula', 'e607fef9', 1, 'yes'),
(2833, 15700, 'Soletis remittunt etsi dederis a roga patria disserendi oratione cognitioque praecepta sane videndum nullam sitne', '51c238ff', 2, 'no'),
(2834, 15701, 'Beate id iucundissime oportere ponis facilior epicurei quin stultorum potero acerrimus estmata', '27769403', 1, 'no'),
(2835, 15701, 'Reliquarum liber tuum luxuriam gubernando debilitas amicos accepimus quoad similia cenasti nostrane adhibendam relinqueret velint', '17b0759a', 2, 'no'),
(2836, 15701, 'Regem desideraret stadia rapior inquit modi frangi sane scias pauca dixisse apta', 'fd875fd6', 3, 'no'),
(2837, 15701, ' [TRUE] - Inscite dicente sironem corpus affectiones quamquam amantissimus effectrix quoque epicuri habes obscurari', '6d9ccf0c', 4, 'yes'),
(2838, 15701, ' [TRUE] - Insipientium utamur perge virtutibus multa catone fortepossumus possitne principes hostes faciant variari', '457c022d', 5, 'yes');
