INSERT INTO `eadact_learnpress_sections` (`section_id`, `section_name`, `section_course_id`, `section_order`, `section_description`) VALUES
(1, 'Capitulo 1', 13927, 1, ''),
(2, 'Capitulo 2', 13927, 2, ''),
(43, 'Section 1', 15008, 0, 'Plebiscito arte moriuntur actum profecti kakan partus pleraque sitis habitus'),
(44, 'Section 2', 15008, 1, 'Perspecta auctoritatem morbo dissentiens dolore diligenter dicta quaeret propria cicuta comparandis enitar faciamus humanis libris'),
(45, 'Section 3', 15008, 2, 'Solebat minime conamini principium tuis populorum promerem dixerim corrigere vivatur valeat kakaw inquieta contrariae anteponebat'),
(46, 'Section 4', 15008, 3, 'Antiocho bene tabulae cavere ptolomaeum iocabor sumus ptolomaeum verecundius nostris firmum domina percipiendas magnitudinis probo'),
(47, 'Section 5', 15008, 4, 'Irridebat filio formosum obruebantur testata viderere omnino dicimus igitur mavis diem quaerimus brevem'),
(48, 'Section 6', 15008, 5, 'Instituendarum sapientia exigit turpiter scaevolam contraria periculum elementa faciant maiora aliter'),
(49, 'Section 7', 15008, 6, 'Libentius efficit volueramus poterunt inventoribus sentit bono sententiis praeclare corpus rapior inportuna dialectice oportere'),
(50, 'Section 1', 15187, 0, 'Magnum cuius ostentatio nunc intellegerem satisfacit adhibendam quemquam probarentur quia vendibiliora epulis iudicari'),
(51, 'Section 2', 15187, 1, 'Pulchritudo finem infame dico summus dices pomponius magnus multo oportere'),
(52, 'Section 3', 15187, 2, 'Nondum ages quid fragile agimus reliquorum sim video ultimum leges'),
(53, 'Section 4', 15187, 3, 'Hominem non exorsus vobis optimus istius contemnit dixerunt chrysippo extrema verecundius sequens'),
(54, 'Section 5', 15187, 4, 'Magna dis tribuunt videres vestris diodorus excitaret ortu censore celebrari sapientes nihilo dolendi vitium iudicari'),
(55, 'Section 1', 15287, 0, 'Iacet gerendus iniquus democriteum proximum dignitati putes diviserunt illae pervertere inveniri'),
(56, 'Section 2', 15287, 1, 'Post libero censes credo alienos ludus noluerunt indicia pomponius confusioque ceteri requiras'),
(57, 'Section 3', 15287, 2, 'Ac id aliquo negotii nosse quaeso theophrastus alias nare fortunae'),
(58, 'Section 4', 15287, 3, 'Optime imperes pulchritudinem nesciebat haesitaret intellegi veniunt chryippo ardentem temperantiam lucius'),
(59, 'Section 5', 15287, 4, 'Iudicabis etsi intrandum oculorum debuerunt crimen ponis ultima facilior agitur praecordiis laboro privatio ingeniosi sollicito'),
(60, 'Section 6', 15287, 5, 'Democriteum animo degendae difficilius eorum auctoritas tantae nobisne copiam finitas sollicito opinor fruitur dissensio malitiam'),
(61, 'Section 7', 15287, 6, 'Sine infantes dices captum nostris rursus intellegunt triarium thorius tota'),
(62, 'Section 8', 15287, 7, 'Disputatione legem extremum controversiam annum aestimaretis dicere quanta quam aeternum antiquis vigeant'),
(63, 'Section 9', 15287, 8, 'Octavio profuso nescius inquam citius sequuntur magis fortuna vanos dubia alia quic'),
(64, 'Section 1', 15475, 0, 'Sequimur malum quivere loqui laudata amicos contraque nepas magos aberrare vivatur negare prohiberet si'),
(65, 'Section 2', 15475, 1, 'Apparet dominorum lectulis diceretur moveatur debeas opus duo amet graeci molestia'),
(66, 'Section 3', 15475, 2, 'Mirabiliter revertendum illo discipulos discordia hilare possint vesperum stabile tuus fingeres pudebit veniunt'),
(67, 'Section 4', 15475, 3, 'Scilicet regem equidem defecerit stabile loquor perspexerit quarum peccetur doctissimi portenta omnes facere probitate intellegi'),
(68, 'Section 5', 15475, 4, 'Profectae singulis improbos audacius persarum expetendam liber expectoque uterque reliquisti sentit'),
(69, 'Section 1', 15552, 0, 'Breve descrição da Section 1'),
(70, 'Section 2', 15552, 1, 'Iocari grata actionemque harum primum nequiter loquantur illos pectus mallem'),
(71, 'Section 3', 15552, 2, 'Delectet dissimiles renovata fidesic medicinae lyco populum ultima e triarius illi iniquum'),
(72, 'Section 4', 15552, 3, 'Semel hoc nos deprehensus constructio malorum ponat auribus diviserunt dissimilis scaevola gloriose eadem infima in'),
(73, 'Section 5', 15552, 4, 'Censent dicerentur mallet expetitur relaxat processerat nimium augeri stabile idem ludus progressionis istius'),
(74, 'Section 6', 15552, 5, 'Exquirere gratia paene vivi chrysippo oris verba videbimus reddes tota ratione dicunt attende commode mundum'),
(75, 'Section 7', 15552, 6, 'Locuples consuli negant natura graeco gubernando quam stoicus pedibus emolumenta'),
(76, 'Section 8', 15552, 7, 'Conveniunt eundem anquam transmisit inscite omni magna emolumenta iudicia tecum pridem videat');
