(7314, 15187, '_lp_info_extra_fast_query', '{\"first_item_id\":15188,\"total_items\":{\"count_items\":\"54\",\"lp_lesson\":\"49\",\"lp_quiz\":\"5\"},\"sections_items\":[{\"id\":\"50\",\"order\":\"0\",\"title\":\"Section 1\",\"description\":\"Magnum cuius ostentatio nunc intellegerem satisfacit adhibendam quemquam probarentur quia vendibiliora epulis iudicari\",\"items\":[{\"id\":\"15188\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15189\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15190\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15191\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15192\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15193\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15194\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15195\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15196\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15197\",\"order\":\"9\",\"type\":\"lp_lesson\"},{\"id\":\"15198\",\"order\":\"10\",\"type\":\"lp_lesson\"},{\"id\":\"15199\",\"order\":\"11\",\"type\":\"lp_lesson\"},{\"id\":\"15200\",\"order\":\"12\",\"type\":\"lp_quiz\"}]},{\"id\":\"51\",\"order\":\"1\",\"title\":\"Section 2\",\"description\":\"Pulchritudo finem infame dico summus dices pomponius magnus multo oportere\",\"items\":[{\"id\":\"15212\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15213\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15214\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15215\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15216\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15217\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15218\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15219\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15220\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15221\",\"order\":\"9\",\"type\":\"lp_quiz\"}]},{\"id\":\"52\",\"order\":\"2\",\"title\":\"Section 3\",\"description\":\"Nondum ages quid fragile agimus reliquorum sim video ultimum leges\",\"items\":[{\"id\":\"15228\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15229\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15230\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15231\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15232\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15233\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15234\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15235\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15236\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15237\",\"order\":\"9\",\"type\":\"lp_lesson\"},{\"id\":\"15238\",\"order\":\"10\",\"type\":\"lp_lesson\"},{\"id\":\"15239\",\"order\":\"11\",\"type\":\"lp_lesson\"},{\"id\":\"15240\",\"order\":\"12\",\"type\":\"lp_lesson\"},{\"id\":\"15241\",\"order\":\"13\",\"type\":\"lp_lesson\"},{\"id\":\"15242\",\"order\":\"14\",\"type\":\"lp_quiz\"}]},{\"id\":\"53\",\"order\":\"3\",\"title\":\"Section 4\",\"description\":\"Hominem non exorsus vobis optimus istius contemnit dixerunt chrysippo extrema verecundius sequens\",\"items\":[{\"id\":\"15251\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15252\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15253\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15254\",\"order\":\"3\",\"type\":\"lp_quiz\"}]},{\"id\":\"54\",\"order\":\"4\",\"title\":\"Section 5\",\"description\":\"Magna dis tribuunt videres vestris diodorus excitaret ortu censore celebrari sapientes nihilo dolendi vitium iudicari\",\"items\":[{\"id\":\"15269\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15270\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15271\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15272\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15273\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15274\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15275\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15276\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15277\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15278\",\"order\":\"9\",\"type\":\"lp_lesson\"},{\"id\":\"15279\",\"order\":\"10\",\"type\":\"lp_lesson\"},{\"id\":\"15280\",\"order\":\"11\",\"type\":\"lp_quiz\"}]}]}'),
