(7717, 15287, '_lp_info_extra_fast_query', '{\"first_item_id\":15288,\"total_items\":{\"count_items\":\"87\",\"lp_lesson\":\"78\",\"lp_quiz\":\"9\"},\"sections_items\":[{\"id\":\"55\",\"order\":\"0\",\"title\":\"Section 1\",\"description\":\"Iacet gerendus iniquus democriteum proximum dignitati putes diviserunt illae pervertere inveniri\",\"items\":[{\"id\":\"15288\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15289\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15290\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15291\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15292\",\"order\":\"4\",\"type\":\"lp_quiz\"}]},{\"id\":\"56\",\"order\":\"1\",\"title\":\"Section 2\",\"description\":\"Post libero censes credo alienos ludus noluerunt indicia pomponius confusioque ceteri requiras\",\"items\":[{\"id\":\"15304\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15305\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15306\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15307\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15308\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15309\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15310\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15311\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15312\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15313\",\"order\":\"9\",\"type\":\"lp_lesson\"},{\"id\":\"15314\",\"order\":\"10\",\"type\":\"lp_lesson\"},{\"id\":\"15315\",\"order\":\"11\",\"type\":\"lp_lesson\"},{\"id\":\"15316\",\"order\":\"12\",\"type\":\"lp_quiz\"}]},{\"id\":\"57\",\"order\":\"2\",\"title\":\"Section 3\",\"description\":\"Ac id aliquo negotii nosse quaeso theophrastus alias nare fortunae\",\"items\":[{\"id\":\"15330\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15331\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15332\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15333\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15334\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15335\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15336\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15337\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15338\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15339\",\"order\":\"9\",\"type\":\"lp_lesson\"},{\"id\":\"15340\",\"order\":\"10\",\"type\":\"lp_lesson\"},{\"id\":\"15341\",\"order\":\"11\",\"type\":\"lp_lesson\"},{\"id\":\"15342\",\"order\":\"12\",\"type\":\"lp_lesson\"},{\"id\":\"15343\",\"order\":\"13\",\"type\":\"lp_quiz\"}]},{\"id\":\"58\",\"order\":\"3\",\"title\":\"Section 4\",\"description\":\"Optime imperes pulchritudinem nesciebat haesitaret intellegi veniunt chryippo ardentem temperantiam lucius\",\"items\":[{\"id\":\"15354\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15355\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15356\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15357\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15358\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15359\",\"order\":\"5\",\"type\":\"lp_quiz\"}]},{\"id\":\"59\",\"order\":\"4\",\"title\":\"Section 5\",\"description\":\"Iudicabis etsi intrandum oculorum debuerunt crimen ponis ultima facilior agitur praecordiis laboro privatio ingeniosi sollicito\",\"items\":[{\"id\":\"15371\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15372\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15373\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15374\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15375\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15376\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15377\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15378\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15379\",\"order\":\"8\",\"type\":\"lp_quiz\"}]},{\"id\":\"60\",\"order\":\"5\",\"title\":\"Section 6\",\"description\":\"Democriteum animo degendae difficilius eorum auctoritas tantae nobisne copiam finitas sollicito opinor fruitur dissensio malitiam\",\"items\":[{\"id\":\"15389\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15390\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15391\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15392\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15393\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15394\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15395\",\"order\":\"6\",\"type\":\"lp_quiz\"}]},{\"id\":\"61\",\"order\":\"6\",\"title\":\"Section 7\",\"description\":\"Sine infantes dices captum nostris rursus intellegunt triarium thorius tota\",\"items\":[{\"id\":\"15402\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15403\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15404\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15405\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15406\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15407\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15408\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15409\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15410\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15411\",\"order\":\"9\",\"type\":\"lp_lesson\"},{\"id\":\"15412\",\"order\":\"10\",\"type\":\"lp_lesson\"},{\"id\":\"15413\",\"order\":\"11\",\"type\":\"lp_lesson\"},{\"id\":\"15414\",\"order\":\"12\",\"type\":\"lp_lesson\"},{\"id\":\"15415\",\"order\":\"13\",\"type\":\"lp_quiz\"}]},{\"id\":\"62\",\"order\":\"7\",\"title\":\"Section 8\",\"description\":\"Disputatione legem extremum controversiam annum aestimaretis dicere quanta quam aeternum antiquis vigeant\",\"items\":[{\"id\":\"15428\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15429\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15430\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15431\",\"order\":\"3\",\"type\":\"lp_quiz\"}]},{\"id\":\"63\",\"order\":\"8\",\"title\":\"Section 9\",\"description\":\"Octavio profuso nescius inquam citius sequuntur magis fortuna vanos dubia alia quic\",\"items\":[{\"id\":\"15446\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15447\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15448\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15449\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15450\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15451\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15452\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15453\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15454\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15455\",\"order\":\"9\",\"type\":\"lp_lesson\"},{\"id\":\"15456\",\"order\":\"10\",\"type\":\"lp_lesson\"},{\"id\":\"15457\",\"order\":\"11\",\"type\":\"lp_lesson\"},{\"id\":\"15458\",\"order\":\"12\",\"type\":\"lp_lesson\"},{\"id\":\"15459\",\"order\":\"13\",\"type\":\"lp_lesson\"},{\"id\":\"15460\",\"order\":\"14\",\"type\":\"lp_quiz\"}]}]}'),
