(7907, 15475, '_lp_info_extra_fast_query', '{\"first_item_id\":15476,\"total_items\":{\"count_items\":\"34\",\"lp_lesson\":\"29\",\"lp_quiz\":\"5\"},\"sections_items\":[{\"id\":\"64\",\"order\":\"0\",\"title\":\"Section 1\",\"description\":\"Sequimur malum quivere loqui laudata amicos contraque nepas magos aberrare vivatur negare prohiberet si\",\"items\":[{\"id\":\"15476\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15477\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15478\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15479\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15480\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15481\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15482\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15483\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15484\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15485\",\"order\":\"9\",\"type\":\"lp_quiz\"}]},{\"id\":\"65\",\"order\":\"1\",\"title\":\"Section 2\",\"description\":\"Apparet dominorum lectulis diceretur moveatur debeas opus duo amet graeci molestia\",\"items\":[{\"id\":\"15492\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15493\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15494\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15495\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15496\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15497\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15498\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15499\",\"order\":\"7\",\"type\":\"lp_quiz\"}]},{\"id\":\"66\",\"order\":\"2\",\"title\":\"Section 3\",\"description\":\"Mirabiliter revertendum illo discipulos discordia hilare possint vesperum stabile tuus fingeres pudebit veniunt\",\"items\":[{\"id\":\"15510\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15511\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15512\",\"order\":\"2\",\"type\":\"lp_lesson\"},{\"id\":\"15513\",\"order\":\"3\",\"type\":\"lp_lesson\"},{\"id\":\"15514\",\"order\":\"4\",\"type\":\"lp_lesson\"},{\"id\":\"15515\",\"order\":\"5\",\"type\":\"lp_lesson\"},{\"id\":\"15516\",\"order\":\"6\",\"type\":\"lp_lesson\"},{\"id\":\"15517\",\"order\":\"7\",\"type\":\"lp_lesson\"},{\"id\":\"15518\",\"order\":\"8\",\"type\":\"lp_lesson\"},{\"id\":\"15519\",\"order\":\"9\",\"type\":\"lp_quiz\"}]},{\"id\":\"67\",\"order\":\"3\",\"title\":\"Section 4\",\"description\":\"Scilicet regem equidem defecerit stabile loquor perspexerit quarum peccetur doctissimi portenta omnes facere probitate intellegi\",\"items\":[{\"id\":\"15533\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15534\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15535\",\"order\":\"2\",\"type\":\"lp_quiz\"}]},{\"id\":\"68\",\"order\":\"4\",\"title\":\"Section 5\",\"description\":\"Profectae singulis improbos audacius persarum expetendam liber expectoque uterque reliquisti sentit\",\"items\":[{\"id\":\"15543\",\"order\":\"0\",\"type\":\"lp_lesson\"},{\"id\":\"15544\",\"order\":\"1\",\"type\":\"lp_lesson\"},{\"id\":\"15545\",\"order\":\"2\",\"type\":\"lp_quiz\"}]}]}'),
