INSERT INTO `eadact_tutor_quiz_questions` (`question_id`, `quiz_id`, `question_title`, `question_description`, `question_type`, `question_mark`, `question_settings`, `question_order`) VALUES
(2, 13907, 'Qual a cor do cavalo branco de Napeleão?', 'Descrição da pergunta 1', 'single_choice', 1.00, 'a:2:{s:13:\"question_type\";s:13:\"single_choice\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(6, 13910, 'A justicafalkkljçfgljksçfdjghsdkjghjk', '', 'single_choice', 1.00, 'a:2:{s:13:\"question_type\";s:13:\"single_choice\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(8, 15795, 'A ISO 55001 pode ser aplicada a:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(9, 15795, 'A ISO 55001 diz que a ISO 55000:2014 - Gestão de ativos - Visão geral, princípios e terminologia é:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 2),
(10, 15795, 'Ao utilizarmos a ISO 55001, podemos ter dúvidas relacionadas a algum termo, por exemplo “ativo”. Neste caso para esclarecimento da definição devemos buscar:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 3),
(11, 15796, 'São exemplos de questões Internas e Externas, nessa ordem:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(12, 15797, 'São exemplos de aspectos que necessitam de critérios relacionados às partes interessadas: Descrição: A ISO 55001:2014 em sua cláusula 4.2 descreve que: “A organização deve determinar as partes interessadas que são pertinentes ao sistema de gestão de ativos e os critérios para a tomada de decisão em gestão de ativos.”', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(13, 15798, 'De acordo com o descrito abaixo, o que deve ser considerado? Descrição: A ISO 55001:2014 em sua cláusula 4.3 descreve que: “A organização deve determinar os limites e aplicabilidade do sistema de gestão de ativos para estabelecer o seu escopo.”', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(14, 15799, 'Ao estabelecer, implementar, manter e continuamente melhorar um sistema de gestão de ativos uma organização deve:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(15, 15800, 'Qual a alternativa que pode ser considerada como correta em relação ao cenário exposto: Descrição: A XKW é uma clínica voltada ao atendimento da população de baixa renda das grandes capitais do País. Recentemente sua alta direção percebeu que um grande fator para o sucesso de suas unidades é a boa gestão dos ativos existentes, sobretudo os equipamentos clínicos e, por isso, buscou a certificação na ISO 55001. Em sua análise de contexto, a alta direção pontuou como questão interna a pouca disponibilidade de recursos financeiros para investimentos. Na análise das partes interessadas estava constituída uma tabela com as necessidades das partes interessadas que excluía o corpo clínico pois, segundo a alta direção, isto demandava muita necessidade de investimentos, o que ia no sentido contrário a pouca disponibilidade de recursos.', '', 'single_choice', 1.00, 'a:2:{s:13:\"question_type\";s:13:\"single_choice\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(16, 15801, 'Segundo a ISO 55001, ao demonstrar liderança e comprometimento com respeito ao sistema de gestão de ativos a alta direção deve:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(17, 15802, 'Segundo a ISO 55001 a alta direção deve estabelecer uma política de gestão de ativos que seja apropriada:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(18, 15803, 'De quem é a responsabilidade pela atribuição do descrito abaixo: Descrição: Segundo a ISO 55001, o plano estratégico de gestão de ativos deve ser estabelecido e atualizado.', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(19, 15804, 'Qual a alternativa que pode ser considerada como correta em relação ao cenário exposto: Descrição: A alta direção da XKW decidiu participar da implantação do SGAt desde o início do projeto. Após entender o que precisava ser feito ela decidiu assumir a responsabilidade pelo estabelecimento e atualização do Plano Estratégico de Gestão de Ativos (SAMP) e pela constituição de um Grupo de Gestão de Ativos que ficou responsável por assegurar os resultados/saídas previstas do SAMP em conjunto com a implantação de um sistema de gestão de ativos adequado aos requisitos da norma ISO 55001. Como este grupo era composto por profissionais de diferentes áreas a decisão foi por não alterar as descrições de cargo, e sim definir os papéis/funções, responsabilidades e autoridades do grupo no próprio SAMP.', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
