(134, 15961, 'Pode ser considerado como um escopo aceitável e certificável de um SGQ:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 2),
(135, 15964, 'Uma organização ao estabelecer, implementar, manter e melhorar continuamente um SGQ, incluindo os processos necessários e suas interações, de acordo com os requisitos da ISO 9001, NÃO necessita:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1),
(136, 15964, 'São considerados processos típicos para um SGQ:', '', 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 2),
(137, 15966, 'São consideradas como questões internas:', NULL, 'single_choice', 1.00, 'a:3:{s:13:\"question_type\";s:13:\"single_choice\";s:15:\"answer_required\";s:1:\"1\";s:13:\"question_mark\";s:4:\"1.00\";}', 1);
