(2183, 367, 'single_choice', 'As mudanças em questões externas e internas que sejam pertinentes para o SGQ e a retroalimentação de partes interessadas pertinentes', 0, 0, NULL, 'text', NULL, 2),
(2184, 367, 'single_choice', 'O desempenho dos processos, a conformidade de produtos e serviços, e a extensão na qual os objetivos da qualidade foram alcançados', 0, 0, NULL, 'text', NULL, 3),
(2185, 367, 'single_choice', 'Todas as alternativas estão corretas', 1, 0, NULL, 'text', NULL, 4),
