(111, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2023-06-03 05:16:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(112, 'woocommerce-WCPayments-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Payments', '<strong>Your store requires a security update for the WooCommerce Payments plugin</strong>. Please update the WooCommerce Payments plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2023-06-07 01:41:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(113, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2023-06-07 01:41:02', NULL, 0, 'plain', '', 0, 0, 'info');
INSERT INTO `eadact_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES
(114, 'woocommerce_hpos_1st_notification_q2_2023', 'marketing', 'en_US', 'High-Performance Order Storage (HPOS) is on its way', 'Our team is targeting August 2023 to roll out a major database upgrade that can unlock faster checkout and order creation for your customers — and lightning-quick order lookup for you. Enablement is optional and you won’t be forced to update, but read on to see why this was our most requested new feature.', '{}', 'unactioned', 'woocommerce.com', '2023-06-07 01:41:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(115, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2023-06-22 05:16:48', NULL, 0, 'plain', '', 0, 0, 'info'),
(116, 'wc-admin-wcpay-bulgaria-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Bulgaria!', 'We’ve recently released WooCommerce Payments in Bulgaria. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '{}', 'pending', 'woocommerce.com', '2023-06-30 02:44:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(117, 'wc-admin-wcpay-czechia-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Czechia!', 'We’ve recently released WooCommerce Payments in Czechia. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '{}', 'pending', 'woocommerce.com', '2023-06-30 02:44:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(118, 'wc-admin-wcpay-croatia-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Croatia!', 'We’ve recently released WooCommerce Payments in Croatia. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '{}', 'pending', 'woocommerce.com', '2023-06-30 02:44:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(119, 'wc-admin-wcpay-hungary-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Hungary!', 'We’ve recently released WooCommerce Payments in Hungary. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '{}', 'pending', 'woocommerce.com', '2023-06-30 02:44:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(120, 'wc-admin-wcpay-romania-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Romania!', 'We’ve recently released WooCommerce Payments in Romania. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '{}', 'pending', 'woocommerce.com', '2023-06-30 02:44:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(121, 'wc-admin-wcpay-sweden-Q2-2023', 'marketing', 'en_US', 'WooCommerce Payments is now available in Sweden!', 'We’ve recently released WooCommerce Payments in Sweden. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.', '{}', 'pending', 'woocommerce.com', '2023-06-30 02:44:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(122, 'tiktok-spc_june-2023', 'marketing', 'en_US', 'Take the guesswork out of TikTok advertising', 'Save time and create smarter ads using new automated campaign management from TikTok for WooCommerce. Simplify your campaign creation and watch TikTok’s machine learning build, target, and optimize ads that support your advertising goals — and grow your audience.', '{}', 'unactioned', 'woocommerce.com', '2023-06-30 02:44:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(123, 'wc-admin-performance-on-mobile', 'info', 'en_US', 'Acompanhe o desempenho da sua loja em dispositivos móveis', 'Monitore suas vendas e produtos com melhor performance com o aplicativo Woo.', '{}', 'unactioned', 'woocommerce-admin', '2023-07-05 05:15:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(124, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2023-07-05 05:15:20', NULL, 0, 'plain', '', 0, 0, 'info'),
(125, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2023-07-06 00:03:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(126, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2023-07-12 00:03:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(127, 'square_payments_q3_2023', 'marketing', 'en_US', 'Square for WooCommerce', 'Connect your Square account with WooCommerce to accept online and in-person payments (including contactless payments and cross-channel gift cards) quickly and securely. Save time by syncing sales, customers, and items and inventory — and manage everything through one centralized platform.', '{}', 'pending', 'woocommerce.com', '2023-07-20 01:51:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(128, 'wc-admin-woopayments-rebrand', 'marketing', 'en_US', 'WooCommerce Payments is now WooPayments', 'We’ve changed the name as part of recent updates to the Woo brand. You’ll still enjoy the same seamless payments experience — just look for WooPayments in your WordPress admin.', '{}', 'pending', 'woocommerce.com', '2023-07-29 05:14:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(129, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2023-08-03 05:15:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(130, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2023-08-03 05:15:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(131, 'woocommerce-WooPayments-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooPayments (WooCommerce Payments) plugin', '<strong>Your shop requires an important security update for the WooPayments (WooCommerce Payments) extension</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2023-08-03 05:15:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(132, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2023-08-03 05:15:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(133, 'tiktok-apac-webinar-2023', 'marketing', 'en_US', 'Unlocking TikTok: Live Webinar August 9', 'Join us on August 9 for a free online masterclass with our partners at TikTok, tailored to Woo merchants in the APAC region (11 am AEST). You’ll learn how to connect your store to TikTok, unlock expert advertising tools, and reach its one billion active global users — all from the comfort of your own home.', '{}', 'pending', 'woocommerce.com', '2023-08-04 23:58:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(134, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2023-08-09 00:17:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(135, 'avalara_q3-2023_withAvaTax', 'marketing', 'en_US', 'New in AvaTax: Calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2023-08-09 00:17:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(136, 'google_uxstudy_recruitment_q3-2023', 'marketing', 'en_US', 'Share your feedback in exchange for $150', 'Woo has teamed up with Google to collect feedback on advertising products and services available to you. If selected, you’ll receive an incentive equal to $150 USD for a 60-minute interview that can help improve the products you use to advertise. If interested, please take 2 minutes to complete the screening survey.', '{}', 'pending', 'woocommerce.com', '2023-08-10 00:20:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(137, 'woo-activation-survey-blockers-22AUG23', 'info', 'en_US', 'How can we help you get that first sale?', 'Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!', '{}', 'pending', 'woocommerce.com', '2023-08-23 00:12:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(138, 'tiktok_shopGTM_q3-2023_hasTikTok', 'marketing', 'en_US', 'You can now sell your products on TikTok Shop', 'TikTok is changing the way shoppers find and connect with brands. With TikTok Shop, you can sync your entire catalog from within Woo and sell directly to TikTok users through in-feed videos, livestreams, and your product showcase tab.', '{}', 'pending', 'woocommerce.com', '2023-09-07 03:33:16', NULL, 0, 'plain', '', 0, 0, 'info'),
(139, 'tiktok_shopGTM_q3-2023_noTikTok', 'marketing', 'en_US', 'You can now sell your products on TikTok Shop', 'TikTok is changing the way shoppers find and connect with brands. With TikTok Shop, you can sync your entire catalog from within Woo and sell directly to TikTok users through in-feed videos, livestreams, and your product showcase tab.', '{}', 'pending', 'woocommerce.com', '2023-09-08 00:17:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(140, 'klaviyo_q3_2023', 'marketing', 'en_US', 'Build long lasting relationships with Klaviyo for WooCommerce', 'Increase customer engagement and boost conversions with powerful email and SMS automation from Klaviyo. Fully integrated with your Woo store, Klaviyo enables you to send personalized communications to your customers — ensuring that the right message is delivered at the right time for maximum impact.', '{}', 'pending', 'woocommerce.com', '2023-09-12 00:23:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(141, 'wc_admin_BNPL_WCPay_Q3_2023', 'marketing', 'en_US', 'Afterpay and Affirm have arrived in WooCommerce Payments!', 'Give your customers more power with buy now, pay later from Afterpay and Affirm — now included as part of WooCommerce Payments! With this new integration, you can quickly offer a checkout option that converts sales and boosts average order value, all from within the same payments dashboard you already know.', '{}', 'pending', 'woocommerce.com', '2023-09-19 00:24:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(142, 'wc_admin_afterpay_WCPay_Q3_2023', 'marketing', 'en_US', 'Afterpay has arrived in WooCommerce Payments!', 'Give your customers more power with buy now, pay later from Afterpay — now included as part of WooCommerce Payments! With this new integration, you can quickly offer a checkout option that converts sales and boosts average order value, all from within the same payments dashboard you already know.', '{}', 'pending', 'woocommerce.com', '2023-09-19 00:24:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(143, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2023-09-20 00:47:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(144, 'wc-admin-edit-products-on-the-move', 'info', 'en_US', 'Edite produtos de qualquer lugar', 'Edite e crie novos produtos do seu dispositivo móvel com o aplicativo Woo', '{}', 'unactioned', 'woocommerce-admin', '2023-10-08 01:00:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(145, 'Klarna_04OCT23', 'marketing', 'en_US', 'Klarna is now available', 'This is a test. Klarna is now available.', '{}', 'pending', 'woocommerce.com', '2023-10-11 00:56:14', NULL, 0, 'plain', '', 0, 0, 'info'),
(146, 'Klarna_10OCT23', 'marketing', 'en_US', 'Klarna is now available', 'This is a test. Klarna is now available.', '{}', 'pending', 'woocommerce.com', '2023-10-12 00:45:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(147, 'wc_com_in_person_payments_card_sale_US_inbox_note_q4_23', 'marketing', 'en_US', 'Save 35% on a WooPayments card reader', 'Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our M2 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends October 29, 2023.', '{}', 'pending', 'woocommerce.com', '2023-10-13 01:16:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(148, 'wc_com_in_person_payments_card_sale_UK_inbox_note_q4_23', 'marketing', 'en_US', 'Save 35% on a WooPayments card reader', 'Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our WisePad 3 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends 29th October 2023.', '{}', 'pending', 'woocommerce.com', '2023-10-13 01:16:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(149, 'wc_com_in_person_payments_card_sale_CA_inbox_note_q4_23', 'marketing', 'en_US', 'Save 35% on a WooPayments card reader', 'Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our WisePad 3 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends October 29, 2023.', '{}', 'pending', 'woocommerce.com', '2023-10-13 01:16:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(150, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2023-10-18 03:29:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(151, 'wc_admin_WooPay_Q4_2023', 'marketing', 'en_US', 'Convert more sales with our fastest checkout yet', 'Enable WooPay and offer the only single-click checkout experience built by Woo, for Woo. Give shoppers the power to pay instantly and securely speed through checkout, even if it\'s their first visit. Add it for free with one tap in your WooPayments dashboard.', '{}', 'pending', 'woocommerce.com', '2023-10-28 00:33:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(152, 'wc_admin_WooPay_Oct30_2023', 'marketing', 'en_US', 'Convert more sales with our fastest checkout yet', 'Enable WooPay and offer the only single-click checkout experience built by Woo, for Woo. Give shoppers the power to pay instantly and securely speed through checkout, even if it\'s their first visit. Add it for free with one tap in your WooPayments dashboard.', '{}', 'pending', 'woocommerce.com', '2023-11-02 23:59:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(153, 'paypal_paylater_q4_23', 'marketing', 'en_US', 'Boost your sales this holiday season with PayPal', 'Set yourself up for success this holiday season by allowing customers to pay the way they prefer. With the latest version of PayPal Payments, you can accept PayPal, Venmo (US), Pay Later*, credit and debit cards, and popular alternative payment methods in one secure solution.', '{}', 'pending', 'woocommerce.com', '2023-11-07 04:00:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(154, 'tap_to_pay_iphone_q4_2023_no_woopayments', 'marketing', 'en_US', 'Accept in-person contactless payments on your iPhone', 'Tap to Pay on iPhone and WooPayments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.', '{}', 'pending', 'woocommerce.com', '2023-12-06 00:29:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(155, 'tap_to_pay_iphone_q4_2023_with_woopayments', 'marketing', 'en_US', 'Accept in-person contactless payments on your iPhone', 'Tap to Pay on iPhone is quick, secure, and simple to set up in WooPayments — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person in a few short steps!', '{}', 'pending', 'woocommerce.com', '2023-12-06 00:29:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(156, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2023-12-07 02:49:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(157, 'amazon_pay_reactivate_q1-24', 'marketing', 'en_US', 'Special offer: Activate 0% promo rate for Amazon Pay', 'For a limited time, Woo merchants who register with Amazon Pay can enjoy a promotional rate of 0% on all transaction fees for 30 days. Valid for businesses based in the United Kingdom. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2024-01-10 04:02:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(158, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2024-01-20 00:18:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(159, 'custom_order_attribution_inbox_q1_2024', 'marketing', 'en_US', 'NEW: Custom Order Attribution', 'Order attribution tracking is now available for all Woo stores! See whether an order came from a search ad, video, or email. Make better marketing decisions and watch your products go from “maybe” to “must-have.”', '{}', 'pending', 'woocommerce.com', '2024-02-06 00:07:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(160, 'wc_admin_UKpricingchange_WCPay_Q1_2024', 'marketing', 'en_US', 'Fee Changes for WooPayments in the EEA and UK', 'WooPayments fees for transactions between the EEA and UK will change as of 1st March, 2024. Transactions between the UK and EEA are now deemed by card networks to be cross-border, thus international payment fees will be applicable. This also changes base processing fees.', '{}', 'pending', 'woocommerce.com', '2024-03-01 00:06:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(161, 'airwallex_q1_2024', 'marketing', 'en_US', 'Save big on foreign exchange (FX) fees', 'Boost your international sales by offering Apple Pay, Google Pay, and 60+ local payment methods with Airwallex. Save time and money by settling payments directly in USD, EUR, HKD, SGD, AUD, and more — without the extra FX fees. Simple, cost-effective, fast.', '{}', 'pending', 'woocommerce.com', '2024-03-01 00:06:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(162, 'checkout_survey_new_users', 'survey', 'en_US', 'We\'d like your feedback on WooCommerce checkout', 'Your feedback is essential for us to improve the WooCommerce checkout and increase your conversion rate, turning more visitors into customers. Answer a few questions to help us understand your experience. It shouldn\'t take more than 5 minutes of your time.', '{}', 'pending', 'woocommerce.com', '2024-04-19 00:30:51', NULL, 0, 'plain', '', 0, 0, 'info'),
(163, 'affirm_q2_2024', 'marketing', 'en_US', 'Boost sales and increase average order value with Affirm!', 'Affirm’s flexible payment options empower customers to get exactly what they want, while making budget-friendly payments. Remove the price barrier and make it even easier for your customers to upgrade, bundle, and add on — with no late fees and clear payment plans. \r\n\r\n* Subject to eligibility. Terms apply.', '{}', 'pending', 'woocommerce.com', '2024-04-25 01:16:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(164, 'checkout_survey_new_users_no_orders', 'survey', 'en_US', 'We\'d like your feedback on WooCommerce checkout', 'Your feedback is essential for us to improve the WooCommerce checkout and increase your conversion rate, turning more visitors into customers. Answer a few questions to help us understand your experience. It shouldn\'t take more than 5 minutes of your time.', '{}', 'pending', 'woocommerce.com', '2024-05-01 00:17:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(165, 'woocommerce-payfast-may-2024-update-needed', 'update', 'en_US', 'An important update is required for the Payfast Payment Gateway', '<strong>Please update to the latest version of the Payfast Payment Gateway for WooCommerce immediately to address a security vulnerability</strong>. This update is required to ensure that your transactions continue to process.', '{}', 'pending', 'woocommerce.com', '2024-05-14 00:12:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(166, 'mailchimp_q2_2024', 'marketing', 'en_US', 'Level up your marketing to boost sales', 'Looking for a smart way to kickstart your growth? Mailchimp’s best-in-class email marketing empowers you to create and automate precisely targeted SMS and email campaigns and build long-term relationships with your audience. Enhance your customer experience, track sales, and more by connecting your store to Mailchimp.', '{}', 'pending', 'woocommerce.com', '2024-06-04 01:05:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(167, 'WC-order-attribution-update-June-2024', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>An important security update for WooCommerce has been released</strong>. It is recommended that you update as quickly as possible.', '{}', 'unactioned', 'woocommerce.com', '2024-06-10 23:58:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(168, 'checkout_block_update_july_2024', 'marketing', 'en_US', 'UPDATE: The checkout block is getting an upgrade!', 'We’re improving the checkout block in 2024, starting with WooCommerce 9.0, launching on June 18! The latest release includes streamlined order summary with sticky functionality, better address form layout, and other enhancements to boost conversion.', '{}', 'pending', 'woocommerce.com', '2024-06-19 00:01:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(169, 'bfcm-survey-jul2024', 'marketing', 'en_US', 'Complete our holiday survey and get a $30 coupon', 'We want to understand how you prepare your store for Black Friday/Cyber Monday and the holidays.\r\n\r\nComplete our 10-minute survey and get $30 USD off an extension from our official Marketplace. Hurry, the survey closes July 15.', '{}', 'pending', 'woocommerce.com', '2024-07-04 00:08:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(170, 'stripe_newcheckout_q3_2024', 'marketing', 'en_US', 'Upgrade your Stripe checkout for even more payment options', 'Boost sales, increase order value, and reach new customers with the new checkout from Stripe. Support 23 payment methods, including buy now, pay later methods like Klarna, Afterpay, and Affirm; Bancontact in Europe and Alipay in Asia; and Link, an accelerated checkout experience that autofills payment information.', '{}', 'pending', 'woocommerce.com', '2024-07-05 00:46:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(171, 'klaviyo_q4_2024', 'marketing', 'en_US', 'Need a marketing solution to help you sell more?', 'Over 13,000 brands use Klaviyo to grow faster. You can drive 46x ROI with their personalized email, SMS, forms, and product reviews. Start for free today.', '{}', 'pending', 'woocommerce.com', '2024-08-01 02:31:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(172, 'wnww-recap-july', 'marketing', 'en_US', 'Powerful updates and upgrades in WooCommerce', 'Have you seen all the latest from Woo? Check out our recent roundup for a look at the newest features, extensions, and insights making WooCommerce perform better than ever.', '{}', 'pending', 'woocommerce.com', '2024-08-14 00:37:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(173, 'bfcm2024-landing-page', 'marketing', 'en_US', 'The best way to prepare for holiday success', 'The upcoming holiday season is the busiest time of the year for many online stores. We want to help you make the most of it with an early gift: our first-ever Black Friday Cyber Monday Trends Report. It\'s full of stats, trends, and recommendations to knock your holiday socks off!', '{}', 'pending', 'woocommerce.com', '2024-09-05 00:22:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(174, 'stripe_securityupdate_q3_2024', 'update', 'en_US', 'Security update required for your Stripe extension', 'To continue securely accepting payments, you must update your Stripe extension to at least version 8.6, re-authenticate, and turn on the new checkout experience. Review the documentation for instructions on how to make the necessary changes from your WooCommerce dashboard.', '{}', 'pending', 'woocommerce.com', '2024-09-19 00:02:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(175, 'paypal_migration_Q3_2024', 'marketing', 'en_US', 'You’re using an outdated version of PayPal', 'Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.', '{}', 'pending', 'woocommerce.com', '2024-10-03 23:52:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(176, 'paypal_migration_Q3_2024_v2', 'marketing', 'en_US', 'You’re using an outdated version of PayPal', 'Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.', '{}', 'pending', 'woocommerce.com', '2024-10-30 23:59:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(177, 'mollie_q4_2024', 'marketing', 'en_US', 'Special offer: Zero transaction fees for your first month with Mollie', 'With seamless checkout, flexible financing, and 30+ local and global payment methods, Mollie is the all-in-one payment solution that enhances the customer experience and helps your business grow. Start your account today and enjoy ZERO transaction fees for the first month. Ts&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2024-11-01 01:51:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(178, 'Renewal_notification_emails_Woosubscriptions_Nov2024', 'marketing', 'en_US', 'WooCommerce Subscriptions just got even better', 'You can now send automatic email reminders to customers before their subscriptions renew or expire. To enable this for your store, update to the latest version of WooCommerce Subscriptions (don\'t forget to make a backup first) and follow the steps linked below.', '{}', 'pending', 'woocommerce.com', '2024-11-18 23:54:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(179, 'paypal_promo_Q4_2024', 'marketing', 'en_US', 'Add PayPal to your existing checkout this holiday season', 'Drive conversion and give customers more confidence to buy when you complement your checkout with PayPal, Venmo, Pay Later, and more. Attract new shoppers and give them a streamlined buying experience with Fastlane, PayPal’s fast and simple guest checkout.', '{}', 'pending', 'woocommerce.com', '2024-11-28 01:23:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(180, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2024-12-05 01:23:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(181, 'usps-mail-service-to-canada-suspended-dec-2024', 'update', 'en_US', 'Please note: USPS Mail Service to Canada Suspended', 'The United States Postal Service has temporarily suspended mail service to Canada due to the ongoing Canadian postal workers\' strike. USPS is asking users to refrain from mailing items to Canada at this time.', '{}', 'pending', 'woocommerce.com', '2024-12-05 23:52:21', NULL, 0, 'plain', '', 0, 0, 'info'),
(182, 'Announce-UPS-WCShipping-Dec2024', 'marketing', 'en_US', 'WooCommerce Shipping now supports select UPS services', 'Give customers the power and reliability of UPS, directly from your dashboard. Access discounted rates, convenient shipping options, and fast, on-time delivery with UPS on WooCommerce Shipping — and stay tuned for UPS® Ground Saver rates coming in 2025.', '{}', 'pending', 'woocommerce.com', '2024-12-12 23:56:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(183, 'account-creation-after-checkout-dec2024', 'marketing', 'en_US', 'Offer account creation after checkout', 'Your customers can now create accounts after they check out on block-based themes. Enable the new “After checkout” block in your account settings and enjoy smoother guest checkout, better conversion, and more repeat business.', '{}', 'pending', 'woocommerce.com', '2024-12-18 23:59:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(184, 'woocommerce-analytics-order-attribution-promotions-december-2024', 'marketing', 'en_US', 'Discover what drives your sales', 'Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.', '{}', 'pending', 'woocommerce.com', '2024-12-24 00:07:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(185, 'affirm_promo_Q1_2025', 'marketing', 'en_US', 'Save up to 50% on merchant fees with Affirm', 'Kickstart the year with buy now, pay later and get merchant rates as low as 2.9% + 30¢ per transaction for 30 days. Download the extension and complete your application from your WooCommerce dashboard by February 19, 2025 to claim the offer. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2025-01-20 23:59:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(186, 'new-woo-brand-announcement-feb4-2025', 'marketing', 'en_US', 'Meet the new Woo', 'WooCommerce has a new look, but underneath, we’re still the same customizable, open-source ecommerce platform you know and love. Plus, we’ve got some major improvements to our platform and product on the way.', '{}', 'pending', 'woocommerce.com', '2025-02-05 01:08:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(187, 'paypal_bnpl_au_promo_Q1_2025', 'marketing', 'en_US', 'Australian shoppers can Pay in 4 with PayPal', 'Enable Pay in 4 messaging to let Australian customers know that they can pay over time while you get paid up front and in full. Pay in 4 is included in PayPal Payments at no additional cost. Eligible buyers can pay in four interest-free payments for purchases of $30 to $2,000 AUD. Terms apply.', '{}', 'pending', 'woocommerce.com', '2025-02-13 00:12:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(188, 'stripe_stripetax_q1_2025', 'marketing', 'en_US', 'Say goodbye to your tax woes', 'Stripe Tax automatically applies the correct sales tax, VAT, or GST, saving time while keeping you compliant. And with simple automatic filing, you can stop stressing at tax time and focus on growing instead.', '{}', 'pending', 'woocommerce.com', '2025-02-20 00:18:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(189, 'printful_promo_q1_2025', 'marketing', 'en_US', 'New: sell print-on-demand products, risk-free', 'Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.', '{}', 'pending', 'woocommerce.com', '2025-02-25 23:58:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(190, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2025-03-04 00:07:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(191, 'woo-marketplace-two-year-subscriptions-rin-2025-03-17', 'marketing', 'en_US', 'Save 20% on new two-year subscriptions', 'We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.', '{}', 'pending', 'woocommerce.com', '2025-03-17 00:00:45', NULL, 0, 'plain', '', 0, 0, 'info'),
(192, 'viva_wallet_migration_q1_2025', 'update', 'en_US', 'Switch to the new Viva.com Smart Checkout', 'The Viva Wallet extension is no longer being updated and improved. To get the best Viva.com experience, move to the new Smart Checkout. It’s fast, secure, and fully compatible with the latest WooCommerce features.', '{}', 'pending', 'woocommerce.com', '2025-04-03 23:54:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(193, 'stripe_orderstatus_bug_q2_2025', 'update', 'en_US', 'Action Required: Update Order Status Manager', 'Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.', '{}', 'pending', 'woocommerce.com', '2025-04-03 23:54:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(194, 'WooCommerce-Stripe-Gateway-Update-April-2025', 'update', 'en_US', 'Action required: Update WooCommerce Stripe Gateway to v9.4.1', '<strong>An important update for WooCommerce Stripe Payment Gateway has been released</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. Please update as soon as possible for optimal store performance. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-18 23:53:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(195, 'WooCommerce-Stripe-Gateway-Update-Info-April-2025', 'update', 'en_US', 'WooCommerce Stripe Gateway has been updated to v9.4.1', '<strong>WooCommerce Stripe Payment Gateway was recently updated</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. No further action is required. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory post </a>for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-18 23:53:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(196, 'klaviyo_q2_2025', 'marketing', 'en_US', 'Tailor your marketing with data-driven automation', 'Deliver personalized experiences at scale, simplify your stack, and make your data work for you using Klaviyo’s best-in-class marketing extension for Woo. With advanced segmentation based on actual customer behavior, you can send email and SMS messages that drive revenue and increase loyalty — without adding complexity', '{}', 'pending', 'woocommerce.com', '2025-04-29 23:54:26', NULL, 0, 'plain', '', 0, 0, 'info'),
(197, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2025-05-05 23:53:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(198, 'payson-retirement-2025', 'update', 'en_US', 'Payson Form Retirement', 'Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.', '{}', 'pending', 'woocommerce.com', '2025-05-13 00:12:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(199, 'paypal_q2_2025', 'marketing', 'en_US', 'Power up sales with Pay Later messaging', 'Help increase your sales and grow cart sizes by letting customers know they have flexible payment options. Merchants see up to an 11% sales lift when they add Pay Later messaging — plus, it integrates seamlessly with your PayPal checkout.', '{}', 'pending', 'woocommerce.com', '2025-05-21 23:58:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(200, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2025-05-30 00:26:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(201, 'tento_q2_2025', 'marketing', 'en_US', 'Get your free business credit score', 'Strong business credit is the key to better deals, stronger partnerships, and sustainable growth. Tento Business Credit Monitoring helps you catch risks early, secure better financing, and fuel smarter growth — with no impact to your credit.', '{}', 'pending', 'woocommerce.com', '2025-06-04 01:48:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(202, 'wc-admin-email-improvements', 'info', 'en_US', 'Your store emails have had an upgrade!', 'We’ve made some exciting improvements to your email templates, including modern, shopper-friendly designs and new customization options. And if you’re using a block theme, you can automatically sync your theme styles! Head to your email settings to explore the new changes.', '{}', 'unactioned', 'woocommerce-admin', '2025-06-11 01:23:20', NULL, 0, 'plain', '', 0, 0, 'info'),
(203, 'woopayments-multibanco-alipay-wechat-launch-2025-06-23', 'marketing', 'en_US', 'Multibanco, AliPay and WeChat now available in WooPayments', 'Multibanco, AliPay, and WeChat Pay are now available in WooPayments! Offer trusted local payment methods to customers in key global markets and boost international sales. Geo restrictions apply.', '{}', 'pending', 'woocommerce.com', '2025-06-24 01:54:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(204, 'woopayments-new-lpms-2025-06-30', 'marketing', 'en_US', 'Get the POS built specifically for Woo stores', 'Introducing WooCommerce POS, our new point-of-sale solution built to get you up and running quickly with in-person sales. Search products, scan barcodes, apply coupons, and send email receipts — right in the WooCommerce mobile app, with all of your online and physical sales synced in real time — no extra setup required', '{}', 'pending', 'woocommerce.com', '2025-06-30 23:53:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(205, 'tiktok-webinar-promo-july2025', 'marketing', 'en_US', 'You\'re Invited: TikTok for WooCommerce Webinar', 'Join us for a free webinar with our friends at TikTok on Tuesday, July 8, at 4 pm UTC. We\'ll cover creative tips and best practices for making content that turns views into sales.', '{}', 'pending', 'woocommerce.com', '2025-06-30 23:53:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(206, 'woopayments-grabpay-launch-2025-07-07', 'marketing', 'en_US', 'GrabPay now available in WooPayments', 'Offer GrabPay through WooPayments and make checkout easier for customers across Southeast Asia. Enable it today and expand your reach with a payment method they know and trust.', '{}', 'pending', 'woocommerce.com', '2025-07-08 00:26:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(207, 'BFCM-25-Survey', 'marketing', 'en_US', 'You’re invited: Take our quick BFCM survey and get 25% off', 'We’re gathering insights on how businesses prepare for peak sales moments like Black Friday and Cyber Monday — so we can better support you. Take our quick 8-minute survey to share your thoughts and get 25% off your next WooCommerce extension as a thank you.', '{}', 'pending', 'woocommerce.com', '2025-07-15 00:51:54', NULL, 0, 'plain', '', 0, 0, 'info'),
(208, 'woohoo10-coupon', 'marketing', 'en_US', 'Celebrate and save with WooCommerce 10.0', 'To mark this milestone release, get 10% off extensions and themes in the official Woo Marketplace. Use code WOOHOO10 at checkout to save on essential tools that help grow your business. Offer ends August 15, 2025. Terms and conditions apply.', '{}', 'unactioned', 'woocommerce.com', '2025-07-22 00:00:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(209, 'paypaladvantage_q3_2025', 'marketing', 'en_US', 'Add PayPal Checkout and earn up to $1,000*', 'PayPal Checkout can boost conversion by up to 46% and average order value by up to 62% with no disruption to your checkout. New US merchants who activate by August 31 save 25% on transaction fees for 6 months. Excludes Venmo. Terms apply.*', '{}', 'pending', 'woocommerce.com', '2025-07-23 01:02:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(210, 'stripe_optimizedcheckout_upgrade_q3_2025', 'marketing', 'en_US', 'Upgrade for a faster, more flexible Stripe checkout', 'You\'re not on the latest WooCommerce Stripe Payment Gateway version. Upgrade to version 9.8 to access Stripe\'s Optimized Checkout Suite and leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-13 23:59:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(211, 'stripe_optimizedcheckout_enable_q3_2025', 'marketing', 'en_US', 'Unlock dynamic payments and sell more', 'You’re on the latest WooCommerce Stripe Payment Gateway — now unlock its full potential by enabling the Optimized Checkout Suite. It uses AI models to dynamically surface the most relevant payment methods for each customer, helping you boost conversions.', '{}', 'pending', 'woocommerce.com', '2025-08-13 23:59:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(212, 'stripe_optimizedcheckout_promotion_q3_2025', 'marketing', 'en_US', 'Upgrade to Stripe for a faster, more flexible checkout', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-16 00:36:30', NULL, 0, 'plain', '', 0, 0, 'info'),
(213, 'woo-subscription-gifting-bundling-2025-08-18', 'marketing', 'en_US', 'Grow recurring revenue with gifting', 'WooCommerce Subscriptions now includes gifting. Customers can buy subscriptions for others, helping you reach new shoppers and grow recurring revenue with less effort. Update to the latest version of Subscriptions (7.8.0) to start offering gifting.', '{}', 'pending', 'woocommerce.com', '2025-08-21 00:14:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(214, 'stripe_optimizedcheckout_competitors_q3_2025', 'marketing', 'en_US', 'Upgrade to the official WooCommerce Stripe Payment Gateway', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Use AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click checkout with Link.', '{}', 'pending', 'woocommerce.com', '2025-08-29 00:06:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(215, 'UPS-promo-RIN-WCS-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-10 23:59:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(216, 'UPS-promo-RIN-WCST-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-10 23:59:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(217, 'square_ordersync_upgrade_q3_2025', 'marketing', 'en_US', 'You asked, we delivered — order sync is here for Square', 'Update your Square extension to v5.0 to access <a href=\"https://woocommerce.com/document/woocommerce-square/sync-settings/sync-orders-between-woocommerce-and-square/\">automatic order syncing</a>. Manage your online sales in Square, keep reports accurate, and save time with order updates visible across both platforms.', '{}', 'pending', 'woocommerce.com', '2025-09-11 23:52:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(218, 'klaviyo_q3_2025', 'marketing', 'en_US', 'Smarter marketing starts with Woo x Klaviyo', 'Personalize every customer interaction with Klaviyo, Woo\'s preferred marketing automation solution. Advanced segmentation based on real customer behavior lets you create email and SMS campaigns focused on driving loyalty and revenue. So you can grow sales while simplifying your stack.', '{}', 'pending', 'woocommerce.com', '2025-09-17 00:36:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(219, 'pinterest_q3_20252', 'marketing', 'en_US', 'More visibility, smarter campaigns', 'Connect your store to Pinterest via the Conversions API, a new feature in the latest version of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Get started today — connect and sync your catalog using the Conversions API.', '{}', 'pending', 'woocommerce.com', '2025-09-24 00:38:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(220, 'ppcp-settings-migration-inbox-note', 'info', 'en_US', '📢 Important: New PayPal Payments settings UI becoming default in October!', 'We\'ve redesigned the settings for better performance and usability. Starting late October, this improved design will be the default for all WooCommerce installations to enjoy faster navigation, cleaner organization, and improved performance. Check out the <a href=\"https://woocommerce.com/document/woocommerce-paypal-payments/paypal-payments-startup-guide/\" target=\"_blank\">Startup Guide</a>, then click <a href=\"#\" name=\"settings-switch-ui\"><strong>Switch to New Settings</strong></a> to activate it.', '{}', 'unactioned', 'woocommerce-paypal-payments/woocommerce-paypal-payments.php', '2025-10-07 18:23:15', NULL, 0, 'plain', '', 0, 0, 'info');
INSERT INTO `eadact_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES
(221, 'pinterest_q4_2025', 'marketing', 'en_US', 'Maximize conversions with Pinterest', 'Connect your store to Pinterest via the Conversions API, now part of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Sync your catalog and create your first ad today.', '{}', 'pending', 'woocommerce.com', '2025-10-22 00:22:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(222, 'paypaladvantage_q4_2025', 'marketing', 'en_US', 'PayPal Checkout offer: Get 40% back on fees for 3 months', 'Download and activate PayPal Payments in your WooCommerce admin, then complete your first transaction by 15 December 2025 to get 40% back on PayPal transaction fees — up to £2,000 for 3 months. PayPal Checkout works with your existing checkout. See terms: paypal.com/uk/campaign/paypalmerchantpromotion/terms.', '{}', 'pending', 'woocommerce.com', '2025-11-05 01:02:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(223, 'reddit_q4_2025', 'marketing', 'en_US', 'New: Reach high-intent shoppers on Reddit', 'Sync your catalog and pixel with Reddit for WooCommerce. Launch your ads faster on Reddit and connect with their 400M+ weekly active users and shoppers who turn to this platform for authentic conversations and recommendations.', '{}', 'pending', 'woocommerce.com', '2025-11-13 23:52:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(224, 'bfcm_general_sale_q4_2025', 'marketing', 'en_US', 'Save up to 40% on extensions and themes', 'For a limited time, take up to 40% off nearly everything in our Marketplace. It’s the perfect moment to give your store a holiday boost and level up for 2026. Sale ends December 2, 2025, at 14:00 UTC.', '{}', 'pending', 'woocommerce.com', '2025-11-20 01:36:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(225, 'paypal-carding-recaptcha-dec-25', 'update', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'unactioned', 'woocommerce.com', '2025-12-05 05:12:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(226, 'Googleupdate_q4_2025', 'marketing', 'en_US', 'Make every ad dollar count this holiday season', 'Google for WooCommerce now includes Budget Recommendations. Install the latest version and get personalized suggestions on where to optimize campaign budgets to reach more holiday shoppers this season.', '{}', 'pending', 'woocommerce.com', '2025-12-05 05:12:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(227, 'holiday_shipping_deadlines_WCST_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 00:09:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(228, 'holiday_shipping_deadlines_WCS_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 00:09:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(229, 'snap_q4_2025', 'marketing', 'en_US', 'New: Reach a new audience on Snapchat', '88% of Snapchatters love to shop, and 40% aren\'t active on other social platforms. Connect with them and grow your business using Snapchat for WooCommerce, our new official extension. Sync your products, launch ad campaigns, and track results — all from your Woo dashboard.', '{}', 'pending', 'woocommerce.com', '2025-12-19 00:11:45', NULL, 0, 'plain', '', 0, 0, 'info'),
(230, 'stripe_agenticcommerce_3PDS_q4_2025', 'marketing', 'en_US', 'Get more from Stripe with the official extension', 'Switch to the official extension co-developed with Stripe for the latest features and best performance. Get access to personalized checkout options, early support for AI shopping through Stripe’s <a href=\"https://woocommerce.com/posts/stripe-agentic-commerce-suite-for-woocommerce/\">Agentic Commerce Suite</a>, and more.', '{}', 'pending', 'woocommerce.com', '2025-12-19 00:11:45', NULL, 0, 'plain', '', 0, 0, 'info'),
(231, 'WC10.4.3-security-update-12-22-2025', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Please update to WooCommerce 10.4.3 to resolve a security issue.</strong> This update addresses an issue with the WooCommerce Store API that may have made guest order information visible to other logged in users. See the <a href=\"https://developer.woocommerce.com/2025/12/22/store-api-vulnerability-patched-in-woocommerce-8-1/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-12-22 23:52:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(232, 'downloads-sub-Jan2026-RIN', 'marketing', 'en_US', 'WooCommerce Subscription Downloads is now part of WooCommerce Subscriptions', 'WooCommerce Subscriptions now allows you to include simple and variable downloadable products with your subscriptions. Streamline your subscription downloads by updating to the latest version of WooCommerce Subscriptions today.', '{}', 'pending', 'woocommerce.com', '2026-01-08 00:12:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(233, 'paypal-carding-recaptcha-jan-26', 'update', 'en_US', 'Fraud protection is now required — enable today', 'Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.', '{}', 'unactioned', 'woocommerce.com', '2026-01-13 00:00:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(234, 'USPS API Migration_RIN_Jan2026', 'marketing', 'en_US', 'Upgrade to USPS Shipping REST API by January 25', 'USPS is retiring the legacy Web Tools API on January 25, 2026. If you’re using the USPS Shipping Method extension with the legacy API, live USPS shipping rates will longer be shown at checkout. Migrate to the REST API now to avoid disruption.', '{}', 'pending', 'woocommerce.com', '2026-01-14 00:22:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(235, 'existing_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2026-01-23 00:26:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(236, 'prospects_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.', '{}', 'pending', 'woocommerce.com', '2026-01-23 00:26:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(237, 'ppcp-recaptcha-protection-note12', 'info', 'en_US', 'Fraud protection is now required — enable today', 'Card networks like Visa, Mastercard and American Express now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.', '{}', 'unactioned', 'woocommerce-paypal-payments/woocommerce-paypal-payments.php', '2026-01-31 10:45:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(238, 'reddit_q1_2026', 'marketing', 'en_US', 'Start advertising on Reddit with a $500 bonus', 'Make the most of our new Reddit integration with $500 in Reddit Ads! For a limited time, new advertisers who spend $500 in Reddit Ads Manager over 30 days will get $500 in ad credit. Your bonus credit unlocks automatically when you hit $500 in spend. Use your credit within 30 days.', '{}', 'pending', 'woocommerce.com', '2026-02-05 13:00:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(239, 'wc-admin-scheduled-updates-promotion', 'info', 'en_US', 'Analytics now supports scheduled updates', 'This provides improved performance to your store, enable it in Analytics &gt; Settings.', '{}', 'unactioned', 'woocommerce-admin', '2026-02-07 13:52:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(240, 'Googleupdate_q1_2026', 'marketing', 'en_US', 'Make every ad dollar count', 'Google for WooCommerce now includes Budget Recommendations. Promote your products across Google — from Search to YouTube and beyond — and get personalized suggestions on where to optimize campaign budgets to reach more shoppers.', '{}', 'pending', 'woocommerce.com', '2026-02-11 00:26:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(241, 'Mailchimp-API-maintenance-feb-2026', 'update', 'en_US', 'Mailchimp Maintenance Feb 28', 'Mailchimp will be carrying out planned API maintenance on February 28 from 11am – 4pm EST. During that time, you may see brief sync interruptions in Mailchimp for WooCommerce. Most data will catch up automatically. See the <a href=\"https://developer.woocommerce.com/2026/02/27/mailchimp-api-maintenance-february-28/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-02-27 04:24:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(242, 'RIN-WC-Security-Update-admin-update-March-2026', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-03-03 00:07:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(243, 'USPS_Scan_Form_Mar2026', 'marketing', 'en_US', 'New: Save time shipping with USPS SCAN Form', 'USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.', '{}', 'pending', 'woocommerce.com', '2026-03-12 01:13:08', NULL, 0, 'plain', '', 0, 0, 'info');
